package internal

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

// The reference is generated by upstream Tree-sitter, not funcfinder navigation.
func TestGooseCodeObjectsCorpus(t *testing.T) {
	path := os.Getenv("FUNC_GOOSE_ORACLE")
	if path == "" {
		t.Skip("set FUNC_GOOSE_ORACLE to the independent exact-byte reference")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var oracle struct {
		Files []struct {
			Path, SHA256, Excluded string
			Objects                []struct {
				Kind, Name, Source string
				Line, Column       int
				EndLine            int `json:"end_line"`
				Start, End         int
			}
		}
	}
	if err := json.Unmarshal(data, &oracle); err != nil {
		t.Fatal(err)
	}
	files, objects, previews := 0, 0, 0
	var findings, exclusions []string
	for _, f := range oracle.Files {
		if f.Excluded != "" {
			exclusions = append(exclusions, f.Path+": "+f.Excluded)
			continue
		}
		src, err := os.ReadFile(f.Path)
		if err != nil {
			t.Fatal(err)
		}
		hash := sha256.Sum256(src)
		if hex.EncodeToString(hash[:]) != f.SHA256 {
			t.Fatal("corpus changed:", f.Path)
		}
		items, err := gooseCodeItems(f.Path, src, "", "module")
		if err != nil {
			findings = append(findings, f.Path+": catalogue refusal: "+err.Error())
			continue
		}
		files++
		var editable []rustObjectItem
		for _, item := range items {
			if item.object.Kind != "" {
				editable = append(editable, item)
			}
		}
		if len(editable) != len(f.Objects) {
			findings = append(findings, fmt.Sprintf("%s: objects got=%d want=%d", f.Path, len(editable), len(f.Objects)))
			continue
		}
		for i, want := range f.Objects {
			item := editable[i]
			o := item.object
			if item.start != want.Start || item.end != want.End || o.Source != want.Source || o.Line != want.Line || o.Column != want.Column || o.EndLine != want.EndLine || o.Name != want.Name || o.Kind != want.Kind {
				findings = append(findings, fmt.Sprintf("%s: span %s got=%d:%d %d..%d want=%d:%d %d..%d", f.Path, want.Name, o.Line, o.Column, item.start, item.end, want.Line, want.Column, want.Start, want.End))
				continue
			}
			objects++
			out, _, err := ReplaceCodeObject(o, src)
			if err != nil || !bytes.Equal(out, src) {
				findings = append(findings, fmt.Sprintf("%s: identity %s: %v", f.Path, o.Name, err))
			} else {
				previews++
			}
		}
	}
	if output := os.Getenv("FUNC_GOOSE_REPORT"); output != "" {
		report, _ := json.MarshalIndent(map[string]any{"oracle": path, "accepted_files": files, "exact_objects": objects, "identity_previews": previews, "excluded": exclusions, "findings": findings}, "", "  ")
		if err := os.WriteFile(output, report, 0600); err != nil {
			t.Fatal(err)
		}
	}
	t.Logf("files=%d exact=%d previews=%d excluded=%d findings=%d", files, objects, previews, len(exclusions), len(findings))
	for i, finding := range findings {
		if i == 20 {
			break
		}
		t.Error(finding)
	}
	if files == 0 || objects == 0 || previews != objects || len(findings) != 0 {
		t.Fail()
	}
}
